using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
public static class TowerFactoryBackgroundPass
{
 const string Folder="Assets/Recoil3D/TowerFactoryBackground",Marker="Tower to factory left - layered industrial background";
 static Material brick,metal,rust,concrete,dark,ceramic,window;
 static Transform G(Transform p,string n,Vector3 at){var t=new GameObject(n).transform;t.SetParent(p,false);t.position=at;return t;}
 static Transform B(Transform p,string n,Vector3 at,Vector3 size,Material m,PrimitiveType type=PrimitiveType.Cube){var t=GameObject.CreatePrimitive(type).transform;t.name=n;t.SetParent(p,false);t.position=at;t.localScale=size;Object.DestroyImmediate(t.GetComponent<Collider>());t.GetComponent<Renderer>().sharedMaterial=m;return t;}
 static Transform Rod(Transform p,string n,Vector3 a,Vector3 b,float r,Material m){var t=B(p,n,(a+b)*.5f,new Vector3(r*2,(a-b).magnitude*.5f,r*2),m,PrimitiveType.Cylinder);t.rotation=Quaternion.FromToRotation(Vector3.up,b-a);return t;}
 static Material Mat(string n,Color c){var path=Folder+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Recoil/3D/Weathered Surface"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.SetFloat("_Glossiness",.08f);m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();}
 static void Building(Transform parent,string name,Vector3 at,Vector3 size){var g=G(parent,name,at);B(g,"Low industrial brick shell",at+Vector3.up*size.y*.5f,size,brick);B(g,"Dark overhanging roof",at+Vector3.up*(size.y+.08f),new Vector3(size.x+.4f,.16f,size.z+.4f),dark);float front=at.z-size.z*.5f-.045f;
  for(int i=0;i<3;i++){float x=at.x-size.x*.32f+i*size.x*.32f;B(g,"High unlit wired window",new Vector3(x,size.y*.70f,front),new Vector3(size.x*.19f,.72f,.08f),dark);for(int j=0;j<3;j++)B(g,"Window mullion",new Vector3(x-size.x*.09f+j*size.x*.09f,size.y*.70f,front-.05f),new Vector3(.04f,.75f,.04f),metal);B(g,"Old window sill",new Vector3(x,size.y*.70f-.40f,front-.07f),new Vector3(size.x*.20f,.08f,.14f),concrete);}
  B(g,"Closed maintenance door",new Vector3(at.x-size.x*.25f,1.16f,front-.02f),new Vector3(1.30f,2.32f,.10f),metal);B(g,"Door lintel",new Vector3(at.x-size.x*.25f,2.35f,front-.06f),new Vector3(1.5f,.11f,.19f),concrete);
  for(int i=0;i<8;i++)B(g,"Wall ventilation louvre",new Vector3(at.x+size.x*.20f,.75f+i*.10f,front-.03f),new Vector3(1.4f,.045f,.10f),metal);
  foreach(float x in new[]{at.x-size.x*.5f+.2f,at.x+size.x*.5f-.2f})Rod(g,"Rainwater downpipe",new Vector3(x,.1f,front-.06f),new Vector3(x,size.y,front-.06f),.04f,rust);
 }
 static void PipeRack(Transform parent,float from,float to,float z,float y){var g=G(parent,"Old elevated utility pipe rack",new Vector3(from,0,z));for(float x=from;x<=to+.1f;x+=6){foreach(float side in new[]{-.95f,.95f})B(g,"Slender pipe rack support",new Vector3(x,y*.5f,z+side),new Vector3(.16f,y,.16f),metal);B(g,"Rack cross beam",new Vector3(x,y-.12f,z),new Vector3(.20f,.20f,2.35f),rust);Rod(g,"Rack diagonal brace",new Vector3(x,.6f,z-.95f),new Vector3(x,y-1,z+.95f),.035f,metal);}
  for(int i=0;i<3;i++){float zz=z-.68f+i*.68f;Rod(g,"Aged horizontal service pipe",new Vector3(from-.3f,y+.12f,zz),new Vector3(to+.3f,y+.12f,zz),i==0?.19f:.10f,metal);for(float x=from+.5f;x<to;x+=4){var t=B(g,"Pipe flange",new Vector3(x,y+.12f,zz),new Vector3(i==0?.46f:.28f,.065f,i==0?.46f:.28f),rust,PrimitiveType.Cylinder);t.rotation=Quaternion.Euler(0,0,90);}}
 }
 static void ElectricalYard(Transform parent){var g=G(parent,"Fenced old transformer and switchgear yard",new Vector3(35,0,7));for(int i=0;i<3;i++){float x=31+i*3.1f;B(g,"Transformer concrete plinth",new Vector3(x,.20f,8),new Vector3(1.9f,.40f,2.05f),concrete);B(g,"Transformer oil tank",new Vector3(x,1.14f,8),new Vector3(1.3f,1.5f,1.55f),metal);for(int f=0;f<7;f++)B(g,"Cooling radiator fin",new Vector3(x-.7f+f*.23f,1.05f,7.13f),new Vector3(.055f,1.15f,.25f),dark);for(int j=0;j<3;j++){var at=new Vector3(x-.42f+j*.42f,2.0f,8);Rod(g,"Porcelain bushing spindle",at,at+Vector3.up*.52f,.045f,ceramic);for(int ring=0;ring<4;ring++)B(g,"Insulator rib",at+Vector3.up*(ring*.12f),new Vector3(.18f,.045f,.18f),ceramic,PrimitiveType.Cylinder);}}
  foreach(float z in new[]{5.8f,10.4f}){for(int i=0;i<6;i++){var at=new Vector3(29.8f+i*1.9f,0,z);Rod(g,"Electrical yard fence post",at,at+Vector3.up*1.75f,.035f,rust);}foreach(float y in new[]{.2f,.9f,1.65f})Rod(g,"Fence wire",new Vector3(29.8f,y,z),new Vector3(39.3f,y,z),.009f,metal);for(int i=0;i<20;i++)Rod(g,"Loose diagonal fence mesh",new Vector3(29.8f+i*.47f,.25f,z),new Vector3(30.2f+i*.47f,1.65f,z),.005f,metal);}
 }
 static void Batch(Transform root){int id=0;foreach(var group in root.GetComponentsInChildren<MeshFilter>().GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial).ToArray()){var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(group.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);string path=Folder+"/Closer background batch "+id+++".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);var t=G(root,"Static background - "+group.Key.name,root.position);t.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=group.Key;foreach(var f in group){Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);}}}
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");var s=SceneManager.GetSceneByPath("Assets/Scenes/3D/RecoilPrototype.unity");if(!s.isLoaded)throw new Exception("Open outdoor scene first");var w=All<RecoilPrototype>(s).Single();if(w.transform.Find(Marker))return "Already applied";string backup="Backups/TowerFactoryBackground/"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";Directory.CreateDirectory(Path.GetDirectoryName(backup));EditorSceneManager.SaveScene(s,backup,true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();
  brick=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Materials/Architecture - metric brick and worn plaster.mat");metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Materials/Worn industrial steel.mat");rust=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Old iron rust.mat");concrete=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Materials/Pitted concrete.mat");dark=Mat("Unlit industrial background recess",new Color(.035f,.048f,.047f));ceramic=Mat("Dull grey porcelain insulators",new Color(.28f,.29f,.25f));window=Mat("One dim occupied service window",new Color(.14f,.115f,.075f));window.EnableKeyword("_EMISSION");window.SetColor("_EmissionColor",new Color(.045f,.032f,.014f));
  var collision=All<Collider2D>(s).Select(c=>c.GetInstanceID()+"|"+c.bounds).ToArray();var routes=All<RecoilDoor>(s).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position).ToArray();var root=G(w.transform,Marker,Vector3.zero);
  Building(root,"Low utility powerhouse behind tower approach",new Vector3(26,0,16),new Vector3(10,4.5f,6.5f));ElectricalYard(root);PipeRack(root,17,41,13,5.2f);
  Building(root,"Far maintenance hall left of office block",new Vector3(52,0,42),new Vector3(21,7.2f,11));PipeRack(root,31,43,28,6.1f);
  foreach(var at in new[]{new Vector3(38,0,33),new Vector3(57,0,52)}){float h=at.x<40?13:16;B(root,"Chimney square footing",at+Vector3.up*.4f,new Vector3(2.3f,.8f,2.3f),concrete);Rod(root,"Slender old boiler chimney",at+Vector3.up*.4f,at+Vector3.up*h,.56f,brick);B(root,"Chimney dark cap",at+Vector3.up*h,new Vector3(1.23f,.17f,1.23f),dark,PrimitiveType.Cylinder);}
  B(root,"Dim high powerhouse window",new Vector3(26,3.15f,12.66f),new Vector3(1.1f,.58f,.03f),window);
  for(int stack=0;stack<3;stack++)for(int i=0;i<4-stack;i++)Rod(root,"Old pipe stock resting on timber sleepers",new Vector3(40.3f+i*.48f,.3f+stack*.36f,21),new Vector3(40.3f+i*.48f,.3f+stack*.36f,25),.18f,rust);
  foreach(float z in new[]{21.4f,24.6f})B(root,"Old pipe stack sleeper",new Vector3(41.0f,.10f,z),new Vector3(2.4f,.2f,.2f),dark);
  Batch(root);if(root.GetComponentsInChildren<Collider>(true).Length+root.GetComponentsInChildren<Collider2D>(true).Length!=0)throw new Exception("Background blockers");if(!collision.SequenceEqual(All<Collider2D>(s).Select(c=>c.GetInstanceID()+"|"+c.bounds)))throw new Exception("Collision changed");if(!routes.SequenceEqual(All<RecoilDoor>(s).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position)))throw new Exception("Routes changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);Directory.CreateDirectory("output/tower-factory-background");string report="PASS utility powerhouse, fenced transformers,2 pipe racks,far maintenance hall,2 slender boiler chimneys and old pipe stock; "+root.GetComponentsInChildren<MeshRenderer>().Length+" static mesh batches; no new lights or collision; routes unchanged. Backup: "+backup;File.WriteAllText("output/tower-factory-background/verification.txt",report);return report;
 }
}
